from lib import *
S = SS('f188')
R = J('f188'); B = R['basic']; P = R['pool']; kp = list(P); H = R['hang']; kh = list(H)
steps = [
    step(f"最简单的数据库就绪检查是 select 1。数据库正常:HTTP {B['up'][2]} {B['up'][0]}({B['up'][1]} ms);数据库停掉:HTTP {B['down'][2]},错误类型 {B['down'][0]},{B['down'][1]} ms 就返回(端口拒绝连接,失败得很快);数据库重新启动后:HTTP {B['back'][2]} {B['back'][0]},应用不用重启(连接池开了 pool_pre_ping)。数据库不通时返回 503,让负载均衡暂时不给这个实例分流量。", t=tl(S(1)), done=lidx(S(1), '数据库正常', '重新启动后'), mark=lidx(S(1), '数据库停掉'), kv=KV([['数据库停掉', f"503,{B['down'][1]} ms"], ['数据库恢复', '不重启应用就恢复']], ['数据库停掉'])),
    step(f"就绪检查走哪个连接池很关键。业务连接池只有 2 个连接,2 个 3 秒的 /slow 请求把它占满:就绪检查走业务池(/ready-shared)要等到有连接空出来,耗时 {P[kp[0]][1]} ms(这次等到了 → {P[kp[0]][0]};如果探针超时比这短,探针会认为失败,尽管数据库其实很健康);给就绪检查用一个独立的、只有 1 个连接的小池(/ready-own),同一时刻 {P[kp[1]][1]} ms 就返回。业务池被占满是应用的负载问题,不是数据库挂了——让就绪检查和业务共用池,会在最忙的时候把实例标成不可用,让剩下的实例更忙。注意:本次测试里没有让 pool_timeout 到期(等待 2.5 s < pool_timeout 3 s),到期后的 TimeoutError 没有单独验证。", t=tl(S(2)), done=lidx(S(2), '独立的 1 连接'), mark=lidx(S(2), '业务连接池'), b=bars([['共用业务池', P[kp[0]][1], f'{P[kp[0]][1]} ms'], ['独立小池', P[kp[1]][1], f'{P[kp[1]][1]} ms']], 2600, mark=[0], done=[1]), kv=KV([['共用业务池', f'{P[kp[0]][1]} ms'], ['独立小池', f'{P[kp[1]][1]} ms']], ['独立小池'])),
    step(f"数据库「卡住」比「挂掉」更危险,因为连接/查询不会失败,只会一直等。端口接受连接但不回应:不设 connect_timeout 时,探针客户端 6 秒后自己放弃({H[kh[0]][2]});connect_timeout=1 后 {H[kh[1]][1]} ms 返回 503(设了 1 秒实际等了约 2 秒:libpq 把小于 2 的 connect_timeout 当 2 处理,与实测一致)。查询很慢(pg_sleep 3 秒):不设 statement_timeout 要 {H[kh[2]][1]} ms 才返回;statement_timeout=500ms 时 {H[kh[3]][1]} ms 就 503。健康检查连接要同时设 connect_timeout 与 statement_timeout,否则探针本身会变成占着 worker 的慢请求。", t=tl(S(3)), done=lidx(S(3), 'connect_timeout=1', 'statement_timeout=500'), mark=lidx(S(3), '不设 connect_timeout', '不设 statement_timeout'), b=bars([['无 connect_timeout', 6000, '≥ 6 s'], ['connect_timeout=1', H[kh[1]][1], f'{H[kh[1]][1]} ms'], ['无 statement_timeout', H[kh[2]][1], f'{H[kh[2]][1]} ms'], ['statement_timeout=500ms', H[kh[3]][1], f'{H[kh[3]][1]} ms']], 6000, mark=[0, 2], done=[1, 3]), kv=KV([['connect_timeout', '必须设,libpq 最小 2 秒'], ['statement_timeout', '必须设']], ['connect_timeout'])),
]
A = mkartf('f188', 188, 'Flask,健康检查,PostgreSQL,SQLAlchemy,连接池,真实验证,动画演示',
    f'用真实的 PostgreSQL 验证数据库就绪检查:select 1 在数据库停掉时 {B["down"][1]} ms 返回 503、恢复后无需重启;就绪检查共用被占满的业务连接池要多等 {P[kp[0]][1]} ms,独立小池只要 {P[kp[1]][1]} ms;数据库卡住时不设 connect_timeout/statement_timeout 探针一直等,设了之后分别在约 2 s 与 {H[kh[3]][1]} ms 返回 503。',
    '数据库的健康检查看起来就是 select 1,但它走哪个连接池、数据库卡住时多久放弃,都会改变探针的含义。这篇用真实的 PostgreSQL 和 gunicorn 逐项验证(健康检查接口的基本形态见第 179 篇,连接重连见第 100 篇)。',
    [(f'{P[kp[0]][1]} → {P[kp[1]][1]} ms', '业务池被占满时,就绪检查共用池 vs 独立小池的耗时'), ('≥ 2 s', '设 connect_timeout=1 实际等待的时间(libpq 最小值)'), (f'{H[kh[3]][1]} ms', 'statement_timeout=500ms 时慢查询的探针耗时')],
    [('select 1', '<p>上一篇:<a href="flask-secret-key-rotation.html">Secret Key 轮换</a>;下一篇:<a href="flask-container-signal-handling.html">容器信号处理</a>。</p><p>数据库是自己起的 PostgreSQL 实例(非默认端口);「卡住」的数据库用一个接受连接但不回应的本地端口模拟。</p>'), ('连接池被占满', None), ('数据库卡住', None)],
    steps, [ENV_F + '。PostgreSQL(自己的实例)、Flask-SQLAlchemy、gunicorn(gthread)', '没有验证:pool_timeout 到期时的 TimeoutError(本次等待短于它)、主从切换与只读副本的健康检查、pgbouncer 等连接代理、检查频率对数据库的负载、云厂商托管数据库的故障表现;「卡住」的数据库只用一个接受连接但不回应的本地端口模拟'], 'Flask 数据库连接健康检查')
